#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.Animations;using UnityEngine;using CityForge.Lots;using CityForge.World;using Object=UnityEngine.Object;
namespace CityForge.EditorTools{
internal static class FoxOakPreparation
{
 internal const string Oak="Assets/CityForge/Resources/Lots/Trees/NMAOak004/",Fox="Assets/CityForge/Resources/Wildlife/ImportedFox/";
 internal static bool HasOak=>AssetDatabase.LoadAssetAtPath<GameObject>(Oak+"Summer.prefab");
 [MenuItem("CityForge/Import/Prepare Fox and NMA Oak")]
 public static void Prepare(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Leave play before asset preparation.");AssetDatabase.Refresh();PrepareOak();PrepareFox();var library=AssetDatabase.LoadAssetAtPath<WildlifeLibrary>("Assets/CityForge/Resources/Wildlife/TemperateWildlife.asset");var entries=library.species.ToList();AppendFox(entries);library.species=entries.ToArray();EditorUtility.SetDirty(library);AssetDatabase.SaveAssets();typeof(LotCatalogSetup).GetMethod("EnsureCatalog",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,null);Debug.Log("FOX AND NMA OAK PREPARED");}
 internal static void AppendFox(List<WildlifeSpecies> entries){var fox=AssetDatabase.LoadAssetAtPath<GameObject>(Fox+"fox.prefab");if(!fox)return;entries.RemoveAll(e=>e.id=="fox");entries.Add(new WildlifeSpecies{id="fox",prefab=fox,habitat=WildlifeHabitat.Woodland,weight=5,speed=.65f});}
 internal static IEnumerable<LotAssetCatalogEntry> OakEntries(){if(!HasOak)yield break;foreach(var id in new[]{"oak-pilot-a","oak-pilot-b"})yield return new LotAssetCatalogEntry{id=id,label=id.EndsWith("a")?"Oak A · NMA 004":"Oak B · NMA 004",category="Trees",group="Deciduous",playerPlaceable=false,preserveTreeMaterials=true,prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Oak+"Summer.prefab"),autumnPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Oak+"Fall.prefab"),winterPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Oak+"Winter.prefab"),footprint=Vector2.one*5};}
 static Material Mat(string path,string color,string normal,Color tint,bool leaves){
 var importer=AssetImporter.GetAtPath(color) as TextureImporter;if(importer&&(importer.maxTextureSize!=2048||leaves&&!importer.alphaIsTransparency)){importer.maxTextureSize=2048;importer.mipmapEnabled=true;importer.alphaIsTransparency=leaves;if(leaves){importer.mipMapsPreserveCoverage=true;importer.alphaTestReferenceValue=.4f;}importer.SaveAndReimport();}
 if(AssetImporter.GetAtPath(normal) is TextureImporter ni&&ni.textureType!=TextureImporterType.NormalMap){ni.textureType=TextureImporterType.NormalMap;ni.maxTextureSize=2048;ni.SaveAndReimport();}
 var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(color));m.SetColor("_BaseColor",tint);m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normal));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.65f);m.SetFloat("_Smoothness",.12f);m.SetFloat("_Metallic",0);m.SetFloat("_Cull",leaves?0:2);m.enableInstancing=true;if(leaves){m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.4f);m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;m.doubleSidedGI=true;}EditorUtility.SetDirty(m);return m;
 }
 static void PrepareOak(){foreach(var season in new[]{"Summer","Fall","Winter"}){var root=new GameObject("NMA Oak 004 · "+season);try{var levels=new List<LOD>();foreach(var file in new[]{"Near.fbx","Middle.fbx","Distant.fbx"}){var source=AssetDatabase.LoadAssetAtPath<GameObject>(Oak+file);if(!source)throw new Exception("Missing oak model "+file);var model=Object.Instantiate(source,root.transform);model.name=file;var renderers=new List<Renderer>();foreach(var renderer in model.GetComponentsInChildren<Renderer>()){
 bool leaves=renderer.name.StartsWith("Leaf_");if(season=="Winter"&&leaves){Object.DestroyImmediate(renderer.gameObject);continue;}string kind=renderer.name.StartsWith("Leaf_A")?"Leaf_A":renderer.name.StartsWith("Leaf_B")?"Leaf_B":"Bark";string color=Oak+kind+(leaves&&season=="Fall"?"-Fall":"")+".png";var mat=Mat(Oak+kind+"-"+season+".mat",color,Oak+kind+"-Normal.jpg",leaves?new Color(.88f,.92f,.83f):new Color(.85f,.80f,.72f),leaves);renderer.sharedMaterials=Enumerable.Repeat(mat,renderer.sharedMaterials.Length).ToArray();renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;renderers.Add(renderer);}
 levels.Add(new LOD(levels.Count==0?.18f:levels.Count==1?.06f:.001f,renderers.ToArray()));}
 var group=root.AddComponent<LODGroup>();group.SetLODs(levels.ToArray());group.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,Oak+season+".prefab");}finally{Object.DestroyImmediate(root);}}}
 static void PrepareFox(){
 var imp=AssetImporter.GetAtPath(Fox+"Model.fbx") as ModelImporter;if(imp&&(imp.animationType!=ModelImporterAnimationType.Generic||imp.avatarSetup!=ModelImporterAvatarSetup.CreateFromThisModel)){imp.animationType=ModelImporterAnimationType.Generic;imp.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;imp.SaveAndReimport();}
 var source=AssetDatabase.LoadAssetAtPath<GameObject>(Fox+"Model.fbx");var far=AssetDatabase.LoadAssetAtPath<GameObject>(Fox+"Distant.fbx");var original=AssetDatabase.LoadAllAssetsAtPath(Fox+"Model.fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview__"));var walk=Object.Instantiate(original);walk.name="Fox Walk";AnimationUtility.SetAnimationEvents(walk,Array.Empty<AnimationEvent>());var settings=AnimationUtility.GetAnimationClipSettings(walk);settings.loopTime=true;settings.keepOriginalPositionXZ=true;AnimationUtility.SetAnimationClipSettings(walk,settings);Store(walk,Fox+"Walk.anim");walk=AssetDatabase.LoadAssetAtPath<AnimationClip>(Fox+"Walk.anim");
 var idle=new AnimationClip{name="Fox Idle",frameRate=30};foreach(var binding in AnimationUtility.GetCurveBindings(walk)){var curve=AnimationUtility.GetEditorCurve(walk,binding);float v=curve.Evaluate(0);AnimationUtility.SetEditorCurve(idle,binding,AnimationCurve.Constant(0,3,v));}var si=AnimationUtility.GetAnimationClipSettings(idle);si.loopTime=true;AnimationUtility.SetAnimationClipSettings(idle,si);Store(idle,Fox+"Idle.anim");idle=AssetDatabase.LoadAssetAtPath<AnimationClip>(Fox+"Idle.anim");
 string cp=Fox+"Fox.controller";var old=AssetDatabase.LoadAssetAtPath<AnimatorController>(cp);if(old)AssetDatabase.DeleteAsset(cp);var controller=AnimatorController.CreateAnimatorControllerAtPath(cp);controller.AddParameter("Moving",AnimatorControllerParameterType.Bool);var sm=controller.layers[0].stateMachine;var still=sm.AddState("Idle");still.motion=idle;var moving=sm.AddState("Walk");moving.motion=walk;sm.defaultState=still;var t=still.AddTransition(moving);t.hasExitTime=false;t.duration=.15f;t.AddCondition(AnimatorConditionMode.If,0,"Moving");t=moving.AddTransition(still);t.hasExitTime=false;t.duration=.15f;t.AddCondition(AnimatorConditionMode.IfNot,0,"Moving");
 var root=new GameObject("Forest fox");try{var model=Object.Instantiate(source,root.transform);var animator=model.GetComponentInChildren<Animator>();if(!animator){animator=model.AddComponent<Animator>();animator.avatar=AssetDatabase.LoadAllAssetsAtPath(Fox+"Model.fbx").OfType<Avatar>().FirstOrDefault();}animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.Rebind();animator.Update(0);idle.SampleAnimation(animator.gameObject,0);
 var head=model.GetComponentsInChildren<Transform>().First(x=>x.name.EndsWith("Head_0"));var spine=model.GetComponentsInChildren<Transform>().First(x=>x.name.EndsWith("Spine_0"));var forward=head.position-spine.position;forward.y=0;model.transform.localRotation=Quaternion.FromToRotation(forward.normalized,Vector3.forward)*model.transform.localRotation;
 var rs=model.GetComponentsInChildren<Renderer>();var b=new Bounds();bool first=true;foreach(var renderer in rs){if(renderer is SkinnedMeshRenderer skinned){var baked=new Mesh();skinned.BakeMesh(baked,true);foreach(var vertex in baked.vertices){var point=skinned.transform.TransformPoint(vertex);if(first){b=new Bounds(point,Vector3.zero);first=false;}else b.Encapsulate(point);}Object.DestroyImmediate(baked);}else {if(first){b=renderer.bounds;first=false;}else b.Encapsulate(renderer.bounds);}}float scale=.48f/b.size.y;model.transform.localScale*=scale;model.transform.localPosition-=new Vector3(b.center.x,b.min.y,b.center.z)*scale;
 var mat=Mat(Fox+"Fox.mat",Fox+"Color.jpg",Fox+"Normal.jpg",new Color(.9f,.88f,.86f),false);foreach(var renderer in rs)renderer.sharedMaterials=Enumerable.Repeat(mat,renderer.sharedMaterials.Length).ToArray();var near=model.GetComponentInChildren<SkinnedMeshRenderer>();var distant=far.GetComponentInChildren<SkinnedMeshRenderer>();if(!near||!distant)throw new Exception("Fox skin missing");
 var farGO=new GameObject("Distant fox",typeof(SkinnedMeshRenderer));farGO.transform.SetParent(near.transform.parent,false);farGO.transform.localPosition=near.transform.localPosition;farGO.transform.localRotation=near.transform.localRotation;farGO.transform.localScale=near.transform.localScale;var farRenderer=farGO.GetComponent<SkinnedMeshRenderer>();farRenderer.sharedMesh=distant.sharedMesh;farRenderer.sharedMaterials=near.sharedMaterials;farRenderer.rootBone=near.rootBone;var bones=near.bones.ToDictionary(x=>x.name,x=>x);farRenderer.bones=distant.bones.Select(x=>bones[x.name]).ToArray();farRenderer.localBounds=near.localBounds;
 var group=root.AddComponent<LODGroup>();group.SetLODs(new[]{new LOD(.07f,new Renderer[]{near}),new LOD(.001f,new Renderer[]{farRenderer})});group.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,Fox+"fox.prefab");}finally{Object.DestroyImmediate(root);}
 }
 static void Store(Object value,string path){var old=AssetDatabase.LoadAssetAtPath<Object>(path);if(old){EditorUtility.CopySerialized(value,old);Object.DestroyImmediate(value);EditorUtility.SetDirty(old);}else AssetDatabase.CreateAsset(value,path);}
}
